if(!connected){$('connectionNotice').hidden=false;$('connectionNotice').innerHTML='The shared order book is not connected yet. Follow the <a href="./setup.html">setup guide</a> to enable admin sign-in, online orders and device syncing.';$('loginForm').querySelector('button').disabled=true;}
window.addEventListener('hashchange',showRoute);window.addEventListener('focus',()=>{if(['#admin','#demo-admin'].includes(location.hash)&&(session||demoMode))loadAdmin(false);else if(!$('cartDialog').open&&!$('successDialog').open)loadProducts();});
let pushEnabled=false;
function notifySummary(list,previous){const real=list.filter(o=>o.source==='website'&&!o.is_test);return{ids:real.map(o=>o.id),fresh:previous?real.filter(o=>!previous.has(o.id)):[]};}
function notifyNewOrders(list){const result=notifySummary(list,seenOrderIds);seenOrderIds=new Set(result.ids);if(demoMode||!result.fresh.length)return;newOrderCount+=result.fresh.length;toast(result.fresh.length+' new customer order'+(result.fresh.length===1?'':'s')+' received. Open Orders to review.');}
function notificationPanel(){return demoMode?'<div class="panel"><h2>Test alerts, without sending.</h2><p>Test orders do not trigger real notifications. Use Preview test alert to see the on-screen message.</p><button data-push-preview>Preview test alert</button></div>':'<div class="panel"><h2>Know when an order arrives.</h2><p>The open dashboard shows an alert when a new customer order arrives. Enable phone notifications for alerts even when this app is closed.</p><p><strong>Device push status: '+(pushEnabled?'enabled':'not enabled')+'</strong></p><div class="actions"><button class="primary" data-push-enable>Enable this device</button><button data-push-preview>Preview device alert</button><button data-push-server-test>Send background test</button><button data-push-disable>Disable this device</button></div><p id="pushStatus" class="muted" role="status"></p><p class="muted">On iPhone, use Safari → Share → Add to Home Screen. Open the installed app, sign in, then tap Enable this device. Background alerts also need the server setup in NOTIFICATIONS.md.</p><p class="muted">Practice orders and imported records never trigger customer-order alerts.</p></div>';}
function pushStatus(message){toast(message);const el=$('pushStatus');if(el)el.textContent=message;}
function urlBytes(value){const raw=atob(value.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-value.length%4)%4));return Uint8Array.from(raw,c=>c.charCodeAt(0));}
async function enablePush(){
 if(demoMode){toast('TEST ALERT · A new customer order has arrived. Nothing was sent to your phone.');return;}
 if(!session)throw Error('Sign in as an administrator first.');
 if(typeof navigator==='undefined'||!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window))throw Error('Push is unavailable here. On iPhone, add the site to your Home Screen and open the installed app.');
 const publicKey=String(config.vapidPublicKey||'');if(!publicKey)throw Error('Complete NOTIFICATIONS.md and add the public VAPID key in config.js first.');
 if(urlBytes(publicKey).length!==65)throw Error('The public VAPID key is invalid. Check config.js.');
 // Request on the button gesture, before waiting for registration/network operations.
 const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notifications were not allowed. You can enable them later in your browser or phone settings.');
 const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBytes(publicKey)});
 try{let userId=session.user?.id;if(!userId){const user=await request('/auth/v1/user',{},true);userId=user.id;}
 await rest('push_subscriptions','?on_conflict=endpoint',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:{admin_id:userId,endpoint:sub.endpoint,subscription:sub.toJSON(),label:'Mo’s Meat admin device'}});
 }catch(e){await sub.unsubscribe();throw e;}pushEnabled=true;if(adminTab==='notifications')renderAdmin();pushStatus('Notifications enabled on this device. Background delivery requires the configured server worker.');
}
