 $('installApp').onclick=async()=>{if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();const choice=await prompt.userChoice;if(choice.outcome==='accepted')$('installApp').hidden=true;return;}
 const file=location.protocol==='file:';$('installMessage').textContent=file?'Install the website after it is hosted on HTTPS (for example, your GitHub Pages address). Opening an HTML file directly cannot install the app.':(typeof navigator!=='undefined'&&/iPhone|iPad|iPod/.test(navigator.userAgent))?'On iPhone or iPad: open this website in Safari, tap Share, then Add to Home Screen. Keep “Open as Web App” enabled if shown, and tap Add.':'Open your browser menu and choose Install app or Add to Home Screen. Some browsers show an install icon beside the address bar. If unavailable, use Chrome, Edge or Safari on a supported device.';$('installDialog').showModal();};
 if(typeof navigator!=='undefined'&&'serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(async reg=>{const sub=await reg.pushManager?.getSubscription();pushEnabled=!!sub;if(adminTab==='notifications'&&session&&!demoMode)renderAdmin();}).catch(()=>{console.warn('Service worker registration unavailable. Check HTTPS and the deployment path.');});
